import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
from rdkit import Chem
x=np.load('full.npy')
lig=Chem.AddHs(Chem.MolFromSmiles('[N-](Cc1ccccn1)C(C)=Nc1c(C)cccc1C'));cp=Chem.AddHs(Chem.MolFromSmiles('[c-]1(C)c(C)c(C)c(C)c1(CC(O)(C(F)(F)F)C(F)(F)F)'))
symbols=[a.GetSymbol() for a in list(lig.GetAtoms())+list(cp.GetAtoms())]+['Rh']
bonds=[]
for m,offset in [(lig,0),(cp,37)]:
 for b in m.GetBonds():bonds.append((b.GetBeginAtomIdx()+offset,b.GetEndAtomIdx()+offset,'solid'))
for i in [0,7,10,37,39,41,43,45]:bonds.append((i,72,'dashed'))
color={'C':'#333333','N':'#2653df','F':'#47b254','O':'#e52d23','H':'#d5d5d5','Rh':'#b340c8'}
fig=plt.figure(figsize=(14,7))
for k,(az,el) in enumerate([(0,15),(95,15)]):
 ax=fig.add_subplot(1,2,k+1,projection='3d')
 for i,j,ls in bonds:
  ax.plot(*np.array([x[i],x[j]]).T,color='gray',lw=1.3 if ls=='solid' else .8,linestyle=ls)
 for i,s in enumerate(symbols):
  ax.scatter(*x[i],s=90 if s not in ['H','Rh'] else (30 if s=='H' else 200),color=color[s],edgecolors='black',linewidth=.3)
  if s in ['N','Rh']:ax.text(*x[i],s+str(i),fontsize=9)
 ax.view_init(elev=el,azim=az);ax.set_box_aspect((1,1,1));ax.set(xlim=(-5,5),ylim=(-5,5),zlim=(-4,6));ax.set_axis_off()
fig.tight_layout();fig.savefig('geometry.png',dpi=160)
# validation
from collections import Counter
print(Counter(symbols))
print('angles')
for a,b in [(0,7),(0,10),(7,10)]:print(a,b,np.degrees(np.arccos(np.dot(x[a],x[b])/np.linalg.norm(x[a])/np.linalg.norm(x[b]))))
dists=np.linalg.norm(x[:37,None,:]-x[None,37:72,:],axis=2)
print('minimum interligand distance',dists.min())
print('file atom count:',len(open('answer.xyz').readlines())-2)
